/**
 * The reactive wrapper around `utils/analytics-access` — DOCB-14282.
 *
 * `canAccessAnalytics()` is pure and knows nothing about stores or the
 * network. This is the piece that feeds it: it reads the preference store and
 * the user's roles, fetches the org's grants once, and exposes the answer as
 * a computed so a component can watch it.
 *
 * ## Why the grants are cached module-wide
 *
 * The answer is per-org, not per-component, and four call sites need it (the
 * side menu on every render, the analytics page, the Touchless gate, the route
 * guard on every navigation). Fetching per caller would put the same request
 * on the wire four times on a cold load and again on every route change. So
 * the in-flight promise is shared and the result is held until something
 * invalidates it.
 *
 * The cache is deliberately NOT time-based. It is invalidated by the two
 * events that can change the answer — an admin saving the roles page, and the
 * acting org changing — and a stale grant list otherwise survives until
 * reload. A TTL here would mean a user who was just granted the tab waits an
 * arbitrary interval to see it, with no way to explain the wait.
 */

import { computed, ref, type ComputedRef, type Ref } from 'vue';
import { storeToRefs } from 'pinia';
import { useSettingStore } from 'src/store/Settings/setting.store';
import { useIsOrgAdmin } from 'src/utils/user-identity';
import { Acl } from 'src/core/acls/index';
import {
  canAccessAnalytics,
  analyticsAccessSettingsReady,
  FEATURE_ANALYTICS_DASHBOARD,
} from 'src/utils/analytics-access';
import { logger } from 'src/utils/logger';

/** The org's grants for the analytics tab. `null` = not fetched yet. */
const allowedRoleIds: Ref<string[] | null> = ref(null);

/** Shared in-flight request, so N callers produce one round trip. */
let inFlight: Promise<string[]> | null = null;

/**
 * Drop the cached grants.
 *
 * Called when an admin saves the roles page (the answer just changed for
 * everyone in the org) and when the acting org changes (the grants are
 * per-org, and serving one org's list to another would be a real leak, not
 * just a stale read).
 */
export function invalidateAnalyticsAccess(): void {
  allowedRoleIds.value = null;
  inFlight = null;
}

/**
 * Fetch the org's grants, joining an in-flight request rather than starting a
 * second one.
 *
 * Fails CLOSED to an empty list: an unreachable endpoint must not be read as
 * "no restrictions". An admin still sees the tab (the admin branch never
 * consults this list), so the failure mode is a granted non-admin briefly
 * losing a tab — recoverable, and far better than the inverse.
 */
export async function loadAnalyticsAccess(force = false): Promise<string[]> {
  if (!force && allowedRoleIds.value !== null) {
    return allowedRoleIds.value;
  }
  if (!force && inFlight) return inFlight;

  inFlight = (async () => {
    try {
      const { documentPermissionsApiService } = await import('src/services');
      const response = await documentPermissionsApiService.getFeatureAccess(
        FEATURE_ANALYTICS_DASHBOARD,
      );
      const ids = Array.isArray(response?.entity_ids)
        ? response.entity_ids.map((id: unknown) => String(id))
        : [];
      allowedRoleIds.value = ids;
      return ids;
    } catch (err) {
      logger.warn('[ANALYTICS-ACCESS] grant lookup failed, denying', err);
      allowedRoleIds.value = [];
      return [];
    } finally {
      inFlight = null;
    }
  })();

  return inFlight;
}

export interface AnalyticsAccessGate {
  /** True once preferences have arrived; nothing may render before it. */
  settingsReady: ComputedRef<boolean>;
  /** Settings loaded AND the user may see the tab. */
  accessGranted: ComputedRef<boolean>;
  /** Settings loaded AND the user may NOT — the banner state. */
  accessDenied: ComputedRef<boolean>;
  /** Uncached evaluation, for the moment just before firing a request. */
  checkAccess: () => boolean;
  /** Loads preferences and grants; resolves when the gate is decidable. */
  ensureLoaded: () => Promise<void>;
}

export function useAnalyticsAccess(): AnalyticsAccessGate {
  const settingStore = useSettingStore();
  const { user_settings } = storeToRefs(settingStore);

  /**
   * Admin lives in LocalStorage, which Vue cannot observe. `useIsOrgAdmin()`
   * wraps it in a computed keyed on the identity version counter, so a role or
   * org change re-evaluates every gate below instead of serving a cached grant
   * to someone who just lost access.
   */
  const isAdmin = useIsOrgAdmin();

  const settingsReady = computed(() =>
    analyticsAccessSettingsReady(user_settings.value),
  );

  const decide = (): boolean =>
    canAccessAnalytics({
      userSettings: user_settings.value,
      isAdmin: isAdmin.value,
      userRoleIds: Acl._getUserGroupIds(),
      allowedRoleIds: allowedRoleIds.value ?? [],
    });

  const accessGranted = computed(() => settingsReady.value && decide());
  const accessDenied = computed(() => settingsReady.value && !decide());

  function checkAccess(): boolean {
    if (!analyticsAccessSettingsReady(settingStore.user_settings)) return false;
    return canAccessAnalytics({
      userSettings: settingStore.user_settings,
      isAdmin: isAdmin.value,
      userRoleIds: Acl._getUserGroupIds(),
      allowedRoleIds: allowedRoleIds.value ?? [],
    });
  }

  async function ensureLoaded(): Promise<void> {
    // Both are fail-open on their own errors and fail-closed in effect: an
    // unknown module state or an unknown grant list resolves to "denied",
    // which is already the right answer, so there is nothing to propagate.
    await Promise.all([
      settingStore.startSettingsFetch().catch(() => undefined),
      Acl.fetchUserGroups().catch(() => undefined),
      loadAnalyticsAccess().catch(() => undefined),
    ]);
  }

  return {
    settingsReady,
    accessGranted,
    accessDenied,
    checkAccess,
    ensureLoaded,
  };
}
